"""End-to-end tests on a small synthetic video generated by FFmpeg (see conftest.py)."""

import json

import pytest

from probing_qc.cli import qc as qc_cli
from probing_qc.imu.telemetry import find_gpmf_stream
from probing_qc.qc import SCHEMA_VERSION, QCConfig, run_qc
from probing_qc.qc.frames import FrameSampler
from probing_qc.qc.metadata import probe_video

pytestmark = pytest.mark.integration

NO_HANDS = {"hands": {"enabled": False}}


def test_probe(synthetic_video):
    info = probe_video(synthetic_video)
    assert (info.width, info.height, info.codec) == (320, 240, "h264")
    assert info.fps == pytest.approx(30) and info.frame_count == 60
    assert not info.has_gpmf


def test_no_gpmf_stream(synthetic_video):
    with pytest.raises(ValueError):
        find_gpmf_stream(synthetic_video)


def test_sampler_takes_every_nth_frame(synthetic_video):
    sampler = FrameSampler(probe_video(synthetic_video), stride=4)
    frames = list(sampler)
    assert [f.index for f in frames] == list(range(0, 60, 4))
    assert frames[1].timestamp_s == pytest.approx(4 / 30)
    assert frames[0].rgb.shape == (240, 320, 3)
    assert sampler.errors == [] and sampler.returncode == 0
    assert sampler.expected_frames == len(frames)


def test_sampler_window(synthetic_video):
    sampler = FrameSampler(probe_video(synthetic_video), stride=2, start_s=1.0, max_seconds=0.5)
    frames = list(sampler)
    assert frames[0].index == 30
    assert abs(len(frames) - sampler.expected_frames) <= 1


def test_sampler_slow_consumer_gets_every_frame(synthetic_video, monkeypatch):
    """Regression: a full prefetch queue at end of stream used to drop the last frame."""
    import time

    import probing_qc.qc.frames as frames_mod

    monkeypatch.setattr(frames_mod, "PREFETCH_FRAMES", 2)
    sampler = FrameSampler(probe_video(synthetic_video), stride=6)
    indices = []
    for frame in sampler:
        time.sleep(0.05)  # analysis slower than decoding -> queue full when ffmpeg finishes
        indices.append(frame.index)
    assert indices == list(range(0, 60, 6))


def test_sampler_early_stop_cleans_up(synthetic_video):
    sampler = FrameSampler(probe_video(synthetic_video), stride=1)
    for _ in zip(range(3), sampler):
        pass
    assert sampler.returncode is not None  # ffmpeg was reaped


def test_run_qc_report_shape(synthetic_video):
    result = run_qc(synthetic_video, QCConfig.from_dict(NO_HANDS), progress=False)
    r = result.report
    json.dumps(r)  # must be serialisable
    assert r["schema_version"] == SCHEMA_VERSION
    assert r["sampling"]["frames_analyzed"] == 15 == len(result.frames)
    tech = r["technical"]
    for key in ("duration", "fps", "bitrate", "codec", "luminance", "sharpness",
                "blockiness", "colour_cast", "decode_errors", "orientation"):
        assert key in tech, key
    assert tech["decode_errors"]["count"] == 0
    assert tech["orientation"]["display"] == "landscape"
    assert "imu" not in tech["orientation"]       # no GPMF in the synthetic video
    assert "hands" not in r
    assert r["config"] == QCConfig.from_dict(NO_HANDS).to_dict()
    assert r["runtime"]["ffmpeg_version"]


def test_run_qc_is_deterministic(synthetic_video):
    cfg = QCConfig.from_dict(NO_HANDS)
    a = run_qc(synthetic_video, cfg, progress=False)
    b = run_qc(synthetic_video, cfg, progress=False)
    strip = lambda r: {k: v for k, v in r.items() if k != "runtime"}  # noqa: E731
    assert strip(a.report) == strip(b.report)
    assert a.frames.equals(b.frames)


def test_qc_cli_writes_outputs(synthetic_video, tmp_path):
    out = tmp_path / "out"
    code = qc_cli.main([str(synthetic_video), "--no-hands", "--frames-csv",
                        "--output-dir", str(out), "--stride", "10"])
    assert code == 0
    report = json.loads((out / "test_qc.json").read_text(encoding="utf-8"))
    assert report["sampling"]["frames_analyzed"] == 6
    assert (out / "test_qc_frames.csv").read_text().count("\n") == 7  # header + 6 rows
